# -*- coding: utf-8 -*-
"""Class 10 Science Chapter 11 Simulators Dictionary"""

simulators = {
  "1": {
    "title": "Electric Charge & Drift Velocity Studio",
    "description": "Visualize electron motion and conventional current in a copper conductor. Contrast random thermal motion against net drift velocity when an electric field is applied, and compute $I = Q/t$.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Electric Field:</span>\n                        <button id=\"sim1_btn_toggle\" onclick=\"sim1ToggleField()\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Field: ON</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Net Charge Q (C):</span>\n                        <input type=\"range\" id=\"sim1_charge_slider\" min=\"1\" max=\"10\" value=\"5\" step=\"0.5\" oninput=\"sim1Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim1_charge_txt\" class=\"text-amber-400 font-mono font-bold\">5.0 C</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Time t (s):</span>\n                        <input type=\"range\" id=\"sim1_time_slider\" min=\"1\" max=\"10\" value=\"2\" step=\"0.5\" oninput=\"sim1Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim1_time_txt\" class=\"text-teal-400 font-mono font-bold\">2.0 s</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim1_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Electric Current (I = Q/t)</div>\n                        <div id=\"sim1_val_current\" class=\"text-amber-400 font-bold text-sm\">2.50 A</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Total Electrons Transferred</div>\n                        <div id=\"sim1_val_electrons\" class=\"text-teal-400 font-bold text-sm\">3.12 \u00d7 10\u00b9\u2079</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Electron Drift Direction</div>\n                        <div id=\"sim1_val_drift\" class=\"text-cyan-400 font-bold text-sm\">Right \u2192 Left (- to +)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Conventional Current</div>\n                        <div id=\"sim1_val_conventional\" class=\"text-emerald-400 font-bold text-sm\">Left \u2192 Right (+ to -)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "2": {
    "title": "Circuit & In-Line Ammeter Laboratory",
    "description": "Construct an electric loop with dry cell, torch bulb, plug key, and series ammeter. Toggle the plug key to observe electron flow, ammeter needle deflection, and filament glow.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Plug Key:</span>\n                        <button id=\"sim2_btn_key\" onclick=\"sim2ToggleKey()\" class=\"px-3 py-1 rounded-lg bg-emerald-600 text-slate-950 font-bold\">Plug Inserted (Closed)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Cell Voltage:</span>\n                        <select id=\"sim2_cell_select\" onchange=\"sim2Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"1.5\">1 Cell (1.5 V)</option>\n                            <option value=\"3.0\" selected>2 Cells (3.0 V)</option>\n                            <option value=\"4.5\">3 Cells (4.5 V)</option>\n                            <option value=\"6.0\">4 Cells (6.0 V)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Bulb Resistance:</span>\n                        <input type=\"range\" id=\"sim2_res_slider\" min=\"5\" max=\"25\" value=\"10\" step=\"1\" oninput=\"sim2Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim2_res_txt\" class=\"text-amber-400 font-mono font-bold\">10 \u03a9</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim2_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Circuit State</div>\n                        <div id=\"sim2_val_state\" class=\"text-emerald-400 font-bold text-sm\">Closed & Continuous</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ammeter Reading (Series)</div>\n                        <div id=\"sim2_val_ammeter\" class=\"text-amber-400 font-bold text-sm\">0.300 A (300 mA)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Lamp Illuminance</div>\n                        <div id=\"sim2_val_glow\" class=\"text-yellow-400 font-bold text-sm\">0.90 W (Bright)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ammeter Internal R</div>\n                        <div id=\"sim2_val_rin\" class=\"text-cyan-400 font-bold text-sm\">\u2248 0 \u03a9 (Negligible)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "3": {
    "title": "Electric Potential Difference & Voltmeter Studio",
    "description": "Simulate work done $W$ against electric fields to transport charge $Q$ between terminals. Connect a high-resistance voltmeter in parallel across circuit components to gauge $V = W/Q$.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Work Done W (J):</span>\n                        <input type=\"range\" id=\"sim3_work_slider\" min=\"6\" max=\"60\" value=\"24\" step=\"2\" oninput=\"sim3Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim3_work_txt\" class=\"text-amber-400 font-mono font-bold\">24 J</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Charge Q (C):</span>\n                        <input type=\"range\" id=\"sim3_charge_slider\" min=\"1\" max=\"10\" value=\"2\" step=\"0.5\" oninput=\"sim3Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim3_charge_txt\" class=\"text-teal-400 font-mono font-bold\">2.0 C</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Voltmeter Tap:</span>\n                        <select id=\"sim3_tap_select\" onchange=\"sim3Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"parallel\">Parallel Across Component</option>\n                            <option value=\"series\">Erroneous Series Connection</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim3_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Potential Difference (V = W/Q)</div>\n                        <div id=\"sim3_val_voltage\" class=\"text-amber-400 font-bold text-sm\">12.0 V</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Volt Definition</div>\n                        <div id=\"sim3_val_unit\" class=\"text-teal-400 font-bold text-sm\">1 V = 1 Joule / 1 Coulomb</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Voltmeter Resistance</div>\n                        <div id=\"sim3_val_voltr\" class=\"text-cyan-400 font-bold text-sm\">Very High (Draws zero I)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Connection Status</div>\n                        <div id=\"sim3_val_status\" class=\"text-emerald-400 font-bold text-sm\">Correct Parallel Hookup</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "4": {
    "title": "Circuit Diagram Symbol Workbench",
    "description": "Inspect and assemble standard NCERT electrical schematic symbols. Click on components to examine their international engineering representations and test interactive switches.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Select Schematic Symbol:</span>\n                        <select id=\"sim4_sym_select\" onchange=\"sim4Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"cell\">1. Electric Cell</option>\n                            <option value=\"battery\">2. Battery of Cells</option>\n                            <option value=\"open_key\">3. Plug Key (Open)</option>\n                            <option value=\"closed_key\">4. Plug Key (Closed)</option>\n                            <option value=\"wire_joint\">5. Wire Joint</option>\n                            <option value=\"wire_cross\">6. Wire Crossing without Joint</option>\n                            <option value=\"bulb\">7. Electric Bulb</option>\n                            <option value=\"resistor\">8. Fixed Resistor</option>\n                            <option value=\"rheostat\">9. Rheostat (Variable R)</option>\n                            <option value=\"ammeter\">10. Ammeter (Series)</option>\n                            <option value=\"voltmeter\">11. Voltmeter (Parallel)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim4CycleNext()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Next Symbol \u2192</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim4_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">NCERT Standard Symbol</div>\n                        <div id=\"sim4_val_name\" class=\"text-amber-400 font-bold text-sm\">Electric Cell</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Function & Role</div>\n                        <div id=\"sim4_val_role\" class=\"text-teal-400 font-bold text-sm\">Maintains potential difference</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Polarity & Connection</div>\n                        <div id=\"sim4_val_polarity\" class=\"text-cyan-400 font-bold text-sm\">Long line (+), Short thick line (-)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "5": {
    "title": "Ohm's Law Activity 11.1 Verification",
    "description": "Replicate Georg Simon Ohm's seminal 1827 experiment. Add cells one by one (1.5 V, 3.0 V, 4.5 V, 6.0 V) across a nichrome wire and observe the constant proportionality $V/I = R$.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Number of 1.5 V Cells:</span>\n                        <div class=\"inline-flex rounded-lg border border-slate-700 p-0.5 bg-slate-800\">\n                            <button id=\"sim5_btn_c1\" onclick=\"sim5SetCells(1)\" class=\"px-2.5 py-0.5 rounded text-xs bg-amber-600 text-slate-950 font-bold\">1 Cell</button>\n                            <button id=\"sim5_btn_c2\" onclick=\"sim5SetCells(2)\" class=\"px-2.5 py-0.5 rounded text-xs text-slate-300\">2 Cells</button>\n                            <button id=\"sim5_btn_c3\" onclick=\"sim5SetCells(3)\" class=\"px-2.5 py-0.5 rounded text-xs text-slate-300\">3 Cells</button>\n                            <button id=\"sim5_btn_c4\" onclick=\"sim5SetCells(4)\" class=\"px-2.5 py-0.5 rounded text-xs text-slate-300\">4 Cells</button>\n                        </div>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Nichrome Wire R:</span>\n                        <input type=\"range\" id=\"sim5_res_slider\" min=\"5\" max=\"20\" value=\"10\" step=\"1\" oninput=\"sim5Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim5_res_txt\" class=\"text-amber-400 font-mono font-bold\">10 \u03a9</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim5_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Terminal Voltage V</div>\n                        <div id=\"sim5_val_voltage\" class=\"text-amber-400 font-bold text-sm\">1.50 V</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Circuit Current I</div>\n                        <div id=\"sim5_val_current\" class=\"text-teal-400 font-bold text-sm\">0.15 A</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ratio V / I</div>\n                        <div id=\"sim5_val_ratio\" class=\"text-cyan-400 font-bold text-sm\">10.00 V/A (\u03a9)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ohmic Status</div>\n                        <div id=\"sim5_val_status\" class=\"text-emerald-400 font-bold text-sm\">Linear Constant R</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "6": {
    "title": "V-I Characteristic Graph & Slope Studio",
    "description": "Plot experimental potential difference $V$ against electric current $I$. Compute the gradient/slope to determine resistance $R$, and compare ohmic metals with varying resistances.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Specimen Conductor:</span>\n                        <select id=\"sim6_wire_select\" onchange=\"sim6Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"copper\">Sample A (Copper Wire - 2 \u03a9)</option>\n                            <option value=\"iron\" selected>Sample B (Nichrome Wire - 10 \u03a9)</option>\n                            <option value=\"nichrome\">Sample C (Thin Constantan - 25 \u03a9)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Sweep Potential V:</span>\n                        <input type=\"range\" id=\"sim6_v_slider\" min=\"0\" max=\"12\" value=\"6\" step=\"0.5\" oninput=\"sim6Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim6_v_txt\" class=\"text-amber-400 font-mono font-bold\">6.0 V</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim6_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Applied Voltage V</div>\n                        <div id=\"sim6_val_v\" class=\"text-amber-400 font-bold text-sm\">6.0 V</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Resulting Current I</div>\n                        <div id=\"sim6_val_i\" class=\"text-teal-400 font-bold text-sm\">0.60 A</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Slope (\u0394V / \u0394I = R)</div>\n                        <div id=\"sim6_val_slope\" class=\"text-cyan-400 font-bold text-sm\">10.0 \u03a9</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Graph Line Profile</div>\n                        <div id=\"sim6_val_line\" class=\"text-emerald-400 font-bold text-sm\">Straight line through origin</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "7": {
    "title": "Resistance Geometric Factors (l, A, Material)",
    "description": "Experiment with Activity 11.3 by altering wire length $l$, cross-sectional area $A$ (thickness), and material to prove the governing formula $R = \\rho l / A$.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Material:</span>\n                        <select id=\"sim7_mat_select\" onchange=\"sim7Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"copper\">Copper (\u03c1 = 1.62 \u00d7 10\u207b\u2078 \u03a9\u00b7m)</option>\n                            <option value=\"aluminium\">Aluminium (\u03c1 = 2.63 \u00d7 10\u207b\u2078 \u03a9\u00b7m)</option>\n                            <option value=\"iron\">Iron (\u03c1 = 10.0 \u00d7 10\u207b\u2078 \u03a9\u00b7m)</option>\n                            <option value=\"nichrome\" selected>Nichrome (\u03c1 = 100 \u00d7 10\u207b\u2078 \u03a9\u00b7m)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Length l (m):</span>\n                        <input type=\"range\" id=\"sim7_len_slider\" min=\"0.5\" max=\"5.0\" value=\"1.0\" step=\"0.5\" oninput=\"sim7Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim7_len_txt\" class=\"text-amber-400 font-mono font-bold\">1.0 m</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Area A (mm\u00b2):</span>\n                        <input type=\"range\" id=\"sim7_area_slider\" min=\"0.2\" max=\"2.0\" value=\"0.5\" step=\"0.1\" oninput=\"sim7Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim7_area_txt\" class=\"text-teal-400 font-mono font-bold\">0.5 mm\u00b2</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim7_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Wire Resistance R</div>\n                        <div id=\"sim7_val_r\" class=\"text-amber-400 font-bold text-sm\">2.00 \u03a9</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Length Effect (R \u221d l)</div>\n                        <div id=\"sim7_val_leffect\" class=\"text-teal-400 font-bold text-sm\">2\u00d7 Length doubles R</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Area Effect (R \u221d 1/A)</div>\n                        <div id=\"sim7_val_aeffect\" class=\"text-cyan-400 font-bold text-sm\">2\u00d7 Area halves R</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Current (at 3 V)</div>\n                        <div id=\"sim7_val_current\" class=\"text-emerald-400 font-bold text-sm\">1.50 A</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "8": {
    "title": "Electrical Resistivity Spectrum Analyzer",
    "description": "Examine the resistivity table across conductors, alloys, and insulators. Discover why nichrome alloy is chosen for toaster and iron heating elements over pure metals.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Category:</span>\n                        <div class=\"inline-flex rounded-lg border border-slate-700 p-0.5 bg-slate-800\">\n                            <button id=\"sim8_btn_cat1\" onclick=\"sim8SetCat('conductor')\" class=\"px-2.5 py-0.5 rounded text-xs bg-amber-600 text-slate-950 font-bold\">Conductors</button>\n                            <button id=\"sim8_btn_cat2\" onclick=\"sim8SetCat('alloy')\" class=\"px-2.5 py-0.5 rounded text-xs text-slate-300\">Alloys</button>\n                            <button id=\"sim8_btn_cat3\" onclick=\"sim8SetCat('insulator')\" class=\"px-2.5 py-0.5 rounded text-xs text-slate-300\">Insulators</button>\n                        </div>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Heating Test:</span>\n                        <button id=\"sim8_btn_heat\" onclick=\"sim8ToggleHeat()\" class=\"px-2.5 py-1 rounded-lg bg-rose-600 text-white font-bold\">Oxidation Stress: ON</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim8_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Resistivity \u03c1 Range</div>\n                        <div id=\"sim8_val_range\" class=\"text-amber-400 font-bold text-sm\">10\u207b\u2078 to 10\u207b\u2076 \u03a9\u00b7m</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">High-Temp Oxidation</div>\n                        <div id=\"sim8_val_oxid\" class=\"text-teal-400 font-bold text-sm\">Alloy does NOT burn</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Typical Application</div>\n                        <div id=\"sim8_val_app\" class=\"text-cyan-400 font-bold text-sm\">Transmission Cables</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Glass / Rubber \u03c1</div>\n                        <div id=\"sim8_val_insul\" class=\"text-emerald-400 font-bold text-sm\">10\u00b9\u00b2 to 10\u00b9\u2077 \u03a9\u00b7m</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "9": {
    "title": "Series Resistors & Ammeter Position Lab",
    "description": "Examine Activity 11.4 with three resistors ($R_1, R_2, R_3$) in series. Shift the ammeter to different positions along the loop to verify that current is identical everywhere.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Ammeter Position:</span>\n                        <select id=\"sim9_pos_select\" onchange=\"sim9Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"before_r1\">Position 1: Before R1</option>\n                            <option value=\"between_r1_r2\" selected>Position 2: Between R1 & R2</option>\n                            <option value=\"between_r2_r3\">Position 3: Between R2 & R3</option>\n                            <option value=\"after_r3\">Position 4: After R3 (Return)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Total Voltage:</span>\n                        <input type=\"range\" id=\"sim9_v_slider\" min=\"3\" max=\"12\" value=\"6\" step=\"1\" oninput=\"sim9Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim9_v_txt\" class=\"text-amber-400 font-mono font-bold\">6 V</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim9_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ammeter Current Reading</div>\n                        <div id=\"sim9_val_i\" class=\"text-amber-400 font-bold text-sm\">0.500 A</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Total Resistance (R_s)</div>\n                        <div id=\"sim9_val_rtot\" class=\"text-teal-400 font-bold text-sm\">12.0 \u03a9 (1+2+3)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Current Invariance</div>\n                        <div id=\"sim9_val_invar\" class=\"text-cyan-400 font-bold text-sm\">Uniform at all points</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Individual Resistors</div>\n                        <div id=\"sim9_val_res\" class=\"text-emerald-400 font-bold text-sm\">R1=2\u03a9, R2=4\u03a9, R3=6\u03a9</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "10": {
    "title": "Series Circuit Analysis & Voltage Drops",
    "description": "Analyze Activity 11.5 and Example 11.7. Measure individual potential drops across each series resistor with a voltmeter to confirm $V = V_1 + V_2 + V_3$ and $R_s = R_1 + R_2 + R_3$.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Preset Scenario:</span>\n                        <select id=\"sim10_preset_select\" onchange=\"sim10UpdatePreset()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"ex11_7\">Example 11.7 (Lamp 20\u03a9 + Wire 4\u03a9 on 6V)</option>\n                            <option value=\"three_r\" selected>Activity 11.5 (R1=2\u03a9, R2=3\u03a9, R3=5\u03a9 on 10V)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Voltmeter Probe:</span>\n                        <select id=\"sim10_probe_select\" onchange=\"sim10Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"total\">Across Complete Combination (V)</option>\n                            <option value=\"v1\">Across Resistor R1 (V1)</option>\n                            <option value=\"v2\">Across Resistor R2 (V2)</option>\n                            <option value=\"v3\">Across Resistor R3 (V3)</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim10_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Equivalent R_s</div>\n                        <div id=\"sim10_val_rs\" class=\"text-amber-400 font-bold text-sm\">10.0 \u03a9</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Loop Current I</div>\n                        <div id=\"sim10_val_i\" class=\"text-teal-400 font-bold text-sm\">1.00 A</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Voltmeter Probe Reading</div>\n                        <div id=\"sim10_val_vprobe\" class=\"text-cyan-400 font-bold text-sm\">V_total = 10.0 V</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Voltage Conservation</div>\n                        <div id=\"sim10_val_sum\" class=\"text-emerald-400 font-bold text-sm\">V = V1 + V2 + V3</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "11": {
    "title": "Parallel Resistor Network & Current Branching",
    "description": "Simulate Activity 11.6 with three parallel resistors. Measure individual branch currents ($I_1, I_2, I_3$) and verify $1/R_p = 1/R_1 + 1/R_2 + 1/R_3$ with identical voltage across all branches.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Total Voltage:</span>\n                        <input type=\"range\" id=\"sim11_v_slider\" min=\"6\" max=\"24\" value=\"12\" step=\"2\" oninput=\"sim11Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim11_v_txt\" class=\"text-amber-400 font-mono font-bold\">12 V</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Branch Switch:</span>\n                        <button id=\"sim11_btn_b1\" onclick=\"sim11ToggleBranch(1)\" class=\"px-2 py-0.5 rounded bg-emerald-700 text-white text-[11px] font-bold\">R1: ON</button>\n                        <button id=\"sim11_btn_b2\" onclick=\"sim11ToggleBranch(2)\" class=\"px-2 py-0.5 rounded bg-emerald-700 text-white text-[11px] font-bold\">R2: ON</button>\n                        <button id=\"sim11_btn_b3\" onclick=\"sim11ToggleBranch(3)\" class=\"px-2 py-0.5 rounded bg-emerald-700 text-white text-[11px] font-bold\">R3: ON</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim11_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Equivalent Resistance (R_p)</div>\n                        <div id=\"sim11_val_rp\" class=\"text-amber-400 font-bold text-sm\">3.33 \u03a9</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Total Current (I = \u03a3 I_k)</div>\n                        <div id=\"sim11_val_itot\" class=\"text-teal-400 font-bold text-sm\">3.60 A</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Branch Currents (I1, I2, I3)</div>\n                        <div id=\"sim11_val_ibranches\" class=\"text-cyan-400 font-bold text-sm\">2.0A, 1.0A, 0.6A</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Voltage Across Each Branch</div>\n                        <div id=\"sim11_val_vbranch\" class=\"text-emerald-400 font-bold text-sm\">Uniform 12.0 V</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "12": {
    "title": "Domestic Parallel vs Series Wiring Lab",
    "description": "Compare domestic parallel circuits with series wiring. Simulate appliance failure in both configurations to understand why home installations mandate parallel connections.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Wiring Topology:</span>\n                        <button id=\"sim12_btn_parallel\" onclick=\"sim12SetTopology('parallel')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Parallel (Domestic)</button>\n                        <button id=\"sim12_btn_series\" onclick=\"sim12SetTopology('series')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Series (Fairy Lights)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Fault Appliance 1:</span>\n                        <button id=\"sim12_btn_fault\" onclick=\"sim12ToggleFault()\" class=\"px-2.5 py-1 rounded-lg bg-rose-600 text-white font-bold\">Blow Bulb 1</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim12_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Bulb 1 (50 W)</div>\n                        <div id=\"sim12_val_app1\" class=\"text-amber-400 font-bold text-sm\">Operating Normal</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ceiling Fan (75 W)</div>\n                        <div id=\"sim12_val_app2\" class=\"text-teal-400 font-bold text-sm\">Operating Normal</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Electric Heater (1500 W)</div>\n                        <div id=\"sim12_val_app3\" class=\"text-cyan-400 font-bold text-sm\">Operating Normal</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Supply Voltage across Loads</div>\n                        <div id=\"sim12_val_voltstatus\" class=\"text-emerald-400 font-bold text-sm\">Each gets full 220 V</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "13": {
    "title": "Joule's Heating Law Calorimeter Studio",
    "description": "Simulate Joule's heating effect ($H = I^2 R t$). Adjust electric current, resistance of heating coil, and duration to measure heat generated and thermal rise in water.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current I (A):</span>\n                        <input type=\"range\" id=\"sim13_i_slider\" min=\"1\" max=\"5\" value=\"2\" step=\"0.5\" oninput=\"sim13Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim13_i_txt\" class=\"text-amber-400 font-mono font-bold\">2.0 A</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Resistance R (\u03a9):</span>\n                        <input type=\"range\" id=\"sim13_r_slider\" min=\"5\" max=\"25\" value=\"10\" step=\"5\" oninput=\"sim13Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim13_r_txt\" class=\"text-teal-400 font-mono font-bold\">10 \u03a9</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Time t (s):</span>\n                        <input type=\"range\" id=\"sim13_t_slider\" min=\"5\" max=\"60\" value=\"20\" step=\"5\" oninput=\"sim13Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim13_t_txt\" class=\"text-cyan-400 font-mono font-bold\">20 s</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim13_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Heat Produced (H = I\u00b2Rt)</div>\n                        <div id=\"sim13_val_heat\" class=\"text-amber-400 font-bold text-sm\">800 J (0.8 kJ)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Thermal Rise (\u0394T)</div>\n                        <div id=\"sim13_val_temp\" class=\"text-rose-400 font-bold text-sm\">+3.8 \u00b0C</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">I\u00b2 Dependency</div>\n                        <div id=\"sim13_val_idep\" class=\"text-cyan-400 font-bold text-sm\">2\u00d7 Current yields 4\u00d7 Heat</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Power Dissipated (P)</div>\n                        <div id=\"sim13_val_power\" class=\"text-emerald-400 font-bold text-sm\">40.0 W (J/s)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "14": {
    "title": "Thermal Appliance & Bulb Filament Studio",
    "description": "Investigate incandescent lamps and electric irons. Observe why high-resistance tungsten filaments glow white-hot at $3380^\\circ\\text{C}$ while copper connecting leads remain cool.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Appliance:</span>\n                        <select id=\"sim14_app_select\" onchange=\"sim14Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"bulb\" selected>Incandescent Bulb (Tungsten 3380\u00b0C)</option>\n                            <option value=\"iron\">Electric Laundry Iron (Nichrome Element)</option>\n                            <option value=\"toaster\">Bread Toaster (Nichrome Ribbon)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Operating Power:</span>\n                        <input type=\"range\" id=\"sim14_power_slider\" min=\"20\" max=\"100\" value=\"80\" step=\"10\" oninput=\"sim14Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim14_power_txt\" class=\"text-amber-400 font-mono font-bold\">80%</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim14_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Filament Temperature</div>\n                        <div id=\"sim14_val_temp\" class=\"text-amber-400 font-bold text-sm\">~2500 \u00b0C (Incandescent)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Gas Filling</div>\n                        <div id=\"sim14_val_gas\" class=\"text-teal-400 font-bold text-sm\">Inactive Nitrogen & Argon</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Copper Connecting Cords</div>\n                        <div id=\"sim14_val_cord\" class=\"text-cyan-400 font-bold text-sm\">Low R: Stays cool (~30\u00b0C)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Melting Point of Tungsten</div>\n                        <div id=\"sim14_val_mp\" class=\"text-rose-400 font-bold text-sm\">3380 \u00b0C (Extremely high)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "15": {
    "title": "Electric Fuse Safety & Meltdown Simulator",
    "description": "Test circuit protection using standard fuse ratings ($1\\text{ A}, 2\\text{ A}, 3\\text{ A}, 5\\text{ A}, 10\\text{ A}$). Simulate an overcurrent event where the fuse melts and saves costly appliances.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Fuse Rating:</span>\n                        <select id=\"sim15_fuse_select\" onchange=\"sim15Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"1\">1 A Fuse</option>\n                            <option value=\"2\">2 A Fuse</option>\n                            <option value=\"3\">3 A Fuse</option>\n                            <option value=\"5\" selected>5 A Fuse (Standard 1 kW load)</option>\n                            <option value=\"10\">10 A Fuse</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Load Current:</span>\n                        <input type=\"range\" id=\"sim15_load_slider\" min=\"1\" max=\"12\" value=\"4.5\" step=\"0.5\" oninput=\"sim15Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim15_load_txt\" class=\"text-amber-400 font-mono font-bold\">4.5 A</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim15TriggerSurge()\" class=\"px-2.5 py-1 rounded-lg bg-rose-600 text-white font-bold\">Simulate Short Circuit</button>\n                        <button onclick=\"sim15ResetFuse()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Replace Fuse</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim15_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Fuse Status</div>\n                        <div id=\"sim15_val_status\" class=\"text-emerald-400 font-bold text-sm\">Intact & Conducting</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Load Appliance State</div>\n                        <div id=\"sim15_val_app\" class=\"text-amber-400 font-bold text-sm\">Protected & Powered</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Fuse Composition</div>\n                        <div id=\"sim15_val_alloy\" class=\"text-cyan-400 font-bold text-sm\">Lead-Tin Low Melting Alloy</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Installation Position</div>\n                        <div id=\"sim15_val_pos\" class=\"text-rose-400 font-bold text-sm\">Series with Live Wire</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "16": {
    "title": "Electric Power & Commercial Energy Meter",
    "description": "Calculate electrical power ($P = VI = I^2 R = V^2 / R$) and commercial consumption in kilowatt-hours ($1\\text{ kWh} = 3.6 \\times 10^6\\text{ J} = 1\\text{ unit}$). Compute monthly electric bill.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Appliance Power:</span>\n                        <input type=\"range\" id=\"sim16_power_slider\" min=\"100\" max=\"2000\" value=\"400\" step=\"50\" oninput=\"sim16Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim16_power_txt\" class=\"text-amber-400 font-mono font-bold\">400 W</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Hours / Day:</span>\n                        <input type=\"range\" id=\"sim16_hours_slider\" min=\"1\" max=\"24\" value=\"8\" step=\"1\" oninput=\"sim16Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim16_hours_txt\" class=\"text-teal-400 font-mono font-bold\">8 hrs/day</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Tariff Rate (\u20b9/unit):</span>\n                        <input type=\"range\" id=\"sim16_tariff_slider\" min=\"2\" max=\"10\" value=\"5\" step=\"0.5\" oninput=\"sim16Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim16_tariff_txt\" class=\"text-cyan-400 font-mono font-bold\">\u20b95.0 / unit</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim16_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Daily Energy Consumed</div>\n                        <div id=\"sim16_val_daily\" class=\"text-amber-400 font-bold text-sm\">3.20 kWh (Units)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Monthly Energy (30 Days)</div>\n                        <div id=\"sim16_val_monthly\" class=\"text-teal-400 font-bold text-sm\">96.0 kWh (Units)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Monthly Bill Cost</div>\n                        <div id=\"sim16_val_bill\" class=\"text-emerald-400 font-bold text-sm\">\u20b9 480.00</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">1 kWh in Joules</div>\n                        <div id=\"sim16_val_joules\" class=\"text-cyan-400 font-bold text-sm\">3.6 \u00d7 10\u2076 Joules</div>\n                    </div>\n                </div>\n            </div>\n        "
  }
}
